"""Restore verified official 2026-10-07 manifest from the GitHub connector snapshot.
The encoded data is an internal transport artifact, not a source of authority: SHA-1
Git blob MUST match the upstream fixed commit content before using the file.
"""
import base64, json, hashlib
from pathlib import Path
PAYLOAD=''''''
packed=base64.b64decode(PAYLOAD)
out=bytearray();i=0
while i<len(packed):
 ch=packed[i];i+=1
 if ch!=255:out.append(ch);continue
 dist=(packed[i]<<8)|packed[i+1];n=packed[i+2]+3;i+=3
 if dist==0:out.append(255);continue
 for j in range(n):out.append(out[-dist])
obj=json.loads(out.decode('utf-8'))
content=(json.dumps(obj,ensure_ascii=False,indent=2)+'\n').encode('utf-8')
sha=hashlib.sha1(b'blob '+str(len(content)).encode()+b'\0'+content).hexdigest()
if sha!='b0bc9dbeedac135f6520b5e93729f63686d97bb4':
 raise SystemExit(f'OFFICIAL BLOB NOT VERIFIED: {sha}')
path=Path(__file__).resolve().parents[2]/'system_dev/v26/semantic_cases.json'
path.parent.mkdir(parents=True,exist_ok=True)
path.write_bytes(content)
print(f'MANIFEST_INSTALLED {path} {len(content)} bytes {sha} {len(obj["cases"])} cases')
